**Step 1: Create the service file with types**

Create `src/services/storage_setup_service.rs`:

```rust
//! Storage setup service for GitHub repository configuration.
//!
//! Handles the async state machine for setting up GitHub repositories,
//! including token validation, repo creation/cloning, and profile discovery.

use crate::config::{Config, GitHubConfig};
use crate::ui::{GitHubSetupData, GitHubSetupStep};
use anyhow::{Context, Result};
use std::path::Path;
use tokio::runtime::Runtime;
use tokio::sync::oneshot;
use tracing::{debug, error, info, warn};

/// Result of a setup step completing
#[derive(Debug, Clone)]
pub enum StepResult {
    /// Move to next step with updated data
    Continue {
        next_step: GitHubSetupStep,
        data: GitHubSetupData,
        status_message: String,
    },
    /// Setup complete - includes profiles found
    Complete {
        profiles: Vec<String>,
        is_new_repo: bool,
    },
    /// Step failed - return to input
    Failed { error_message: String },
}

/// Handle for polling async step progress
pub struct StepHandle {
    pub receiver: oneshot::Receiver<Result<StepResult>>,
}

/// Service for handling GitHub storage setup
pub struct StorageSetupService;

impl StorageSetupService {
    /// Start an async setup step - returns immediately with a handle to poll
    pub fn start_step(
        step: GitHubSetupStep,
        data: GitHubSetupData,
        config: Config,
        runtime: &Runtime,
    ) -> StepHandle {
        let (tx, rx) = oneshot::channel();

        runtime.spawn(async move {
            let result = Self::process_step_async(step, data, config).await;
            let _ = tx.send(result);
        });

        StepHandle { receiver: rx }
    }

    /// Process a single step asynchronously
    async fn process_step_async(
        step: GitHubSetupStep,
        mut data: GitHubSetupData,
        config: Config,
    ) -> Result<StepResult> {
        match step {
            GitHubSetupStep::Connecting => {
                // Simulated delay for UX
                tokio::time::sleep(std::time::Duration::from_millis(500)).await;
                Ok(StepResult::Continue {
                    next_step: GitHubSetupStep::ValidatingToken,
                    data,
                    status_message: "🔑 Validating your token...".to_string(),
                })
            }
            GitHubSetupStep::ValidatingToken => {
                Self::handle_validating_token(&mut data).await
            }
            GitHubSetupStep::CheckingRepo => {
                Self::handle_checking_repo(&data).await
            }
            GitHubSetupStep::CloningRepo => {
                Self::handle_cloning_repo(&data, &config).await
            }
            GitHubSetupStep::CreatingRepo => {
                Self::handle_creating_repo(&mut data).await
            }
            GitHubSetupStep::InitializingRepo => {
                Self::handle_initializing_repo(&mut data, &config).await
            }
            GitHubSetupStep::DiscoveringProfiles => {
                Self::handle_discovering_profiles(&data, &config).await
            }
            GitHubSetupStep::Complete => {
                // This shouldn't be called as a step - Complete is a terminal state
                Ok(StepResult::Complete {
                    profiles: Vec::new(),
                    is_new_repo: data.is_new_repo,
                })
            }
        }
    }

    async fn handle_validating_token(data: &mut GitHubSetupData) -> Result<StepResult> {
        use crate::github::GitHubClient;

        let client = GitHubClient::new(data.token.clone());
        let user = client.get_user().await?;
        let repo_exists = client.repo_exists(&user.login, &data.repo_name).await?;

        data.username = Some(user.login);
        data.repo_exists = Some(repo_exists);

        Ok(StepResult::Continue {
            next_step: GitHubSetupStep::CheckingRepo,
            data: data.clone(),
            status_message: "🔍 Checking if repository exists...".to_string(),
        })
    }

    async fn handle_checking_repo(data: &GitHubSetupData) -> Result<StepResult> {
        let username = data.username.as_ref()
            .context("Username not set in CheckingRepo step")?;

        if data.repo_exists == Some(true) {
            Ok(StepResult::Continue {
                next_step: GitHubSetupStep::CloningRepo,
                data: data.clone(),
                status_message: format!("📥 Cloning repository {}/{}...", username, data.repo_name),
            })
        } else {
            Ok(StepResult::Continue {
                next_step: GitHubSetupStep::CreatingRepo,
                data: data.clone(),
                status_message: format!("📦 Creating repository {}/{}...", username, data.repo_name),
            })
        }
    }

    async fn handle_cloning_repo(data: &GitHubSetupData, config: &Config) -> Result<StepResult> {
        use crate::git::GitManager;

        let username = data.username.as_ref()
            .context("Username not set in CloningRepo step")?;
        let remote_url = format!(
            "https://github.com/{}/{}.git",
            username, data.repo_name
        );

        // Clone is a blocking operation, run in spawn_blocking
        let repo_path = config.repo_path.clone();
        let token = data.token.clone();
        let data_clone = data.clone();

        let clone_result = tokio::task::spawn_blocking(move || {
            GitManager::clone_or_open(&remote_url, &repo_path, Some(&token))
        }).await??;

        let (_git_mgr, was_existing) = clone_result;

        let status = if was_existing {
            "✅ Using existing repository!"
        } else {
            "✅ Repository cloned successfully!"
        };

        Ok(StepResult::Continue {
            next_step: GitHubSetupStep::DiscoveringProfiles,
            data: data_clone,
            status_message: status.to_string(),
        })
    }

    async fn handle_creating_repo(data: &mut GitHubSetupData) -> Result<StepResult> {
        use crate::github::GitHubClient;

        let client = GitHubClient::new(data.token.clone());
        client
            .create_repo(&data.repo_name, "My dotfiles managed by dotstate", data.is_private)
            .await?;

        data.is_new_repo = true;

        Ok(StepResult::Continue {
            next_step: GitHubSetupStep::InitializingRepo,
            data: data.clone(),
            status_message: "⚙️  Initializing local repository...".to_string(),
        })
    }

    async fn handle_initializing_repo(
        data: &mut GitHubSetupData,
        config: &Config,
    ) -> Result<StepResult> {
        use crate::git::GitManager;
        use crate::utils::ProfileManifest;

        let username = data.username.as_ref()
            .context("Username not set in InitializingRepo step")?;
        let token = data.token.clone();
        let repo_name = data.repo_name.clone();
        let repo_path = config.repo_path.clone();
        let default_branch = config.default_branch.clone();
        let active_profile = config.active_profile.clone();
        let username_clone = username.clone();

        // Run blocking git operations
        let default_profile_name = tokio::task::spawn_blocking(move || -> Result<String> {
            std::fs::create_dir_all(&repo_path)
                .context("Failed to create repository directory")?;

            let mut git_mgr = GitManager::open_or_init(&repo_path)?;

            // Add remote
            let remote_url = format!(
                "https://{}@github.com/{}/{}.git",
                token, username_clone, repo_name
            );
            git_mgr.add_remote("origin", &remote_url)?;

            // Create initial commit
            std::fs::write(
                repo_path.join("README.md"),
                format!("# {}\n\nDotfiles managed by dotstate", repo_name),
            )?;

            // Create profile manifest with default profile
            let default_profile_name = if active_profile.is_empty() {
                "Personal".to_string()
            } else {
                active_profile
            };

            let manifest = ProfileManifest {
                common: crate::utils::profile_manifest::CommonSection::default(),
                profiles: vec![crate::utils::profile_manifest::ProfileInfo {
                    name: default_profile_name.clone(),
                    description: None,
                    synced_files: Vec::new(),
                    packages: Vec::new(),
                }],
            };
            manifest.save(&repo_path)?;

            git_mgr.commit_all("Initial commit")?;

            let current_branch = git_mgr
                .get_current_branch()
                .unwrap_or(default_branch);

            // Try to pull before push (for existing remote content)
            if let Err(e) = git_mgr.pull("origin", &current_branch, Some(&token)) {
                info!("Could not pull from remote (normal for new repos): {}", e);
            }

            git_mgr
                .push("origin", &current_branch, Some(&token))
                .context("Failed to push to remote")?;

            if let Err(e) = git_mgr.set_upstream_tracking("origin", &current_branch) {
                warn!("Failed to set upstream tracking: {}", e);
            }

            Ok(default_profile_name)
        }).await??;

        data.is_new_repo = true;

        Ok(StepResult::Complete {
            profiles: vec![default_profile_name],
            is_new_repo: true,
        })
    }

    async fn handle_discovering_profiles(
        data: &GitHubSetupData,
        config: &Config,
    ) -> Result<StepResult> {
        use crate::utils::ProfileManifest;

        let repo_path = config.repo_path.clone();

        let profiles = tokio::task::spawn_blocking(move || -> Result<Vec<String>> {
            let manifest = ProfileManifest::load_or_backfill(&repo_path)?;
            Ok(manifest.profiles.iter().map(|p| p.name.clone()).collect())
        }).await??;

        Ok(StepResult::Complete {
            profiles,
            is_new_repo: data.is_new_repo,
        })
    }

    /// Cleanup after failed setup - resets config and optionally removes repo
    pub fn cleanup_failed_setup(
        config: &mut Config,
        config_path: &Path,
        cleanup_repo: bool,
    ) {
        info!("Cleaning up failed setup state");

        // Clean up repo directory if requested
        if cleanup_repo && config.repo_path.exists() {
            if config.repo_path.join(".git").exists() {
                info!("Removing partially created repo at {:?}", config.repo_path);
                if let Err(e) = std::fs::remove_dir_all(&config.repo_path) {
                    warn!("Failed to clean up repo directory: {}", e);
                }
            }
        }

        // Reset config to unconfigured state
        config.reset_to_unconfigured();

        // Save the reset config
        if let Err(e) = config.save(config_path) {
            warn!("Failed to save reset config: {}", e);
        }
    }
}
