**Step 2: Add process_action method to DotfileSelectionScreen impl**

Add this method to the `impl DotfileSelectionScreen` block (before the Screen trait impl):

```rust
    /// Process a dotfile-specific action
    pub fn process_action(
        &mut self,
        action: DotfileAction,
        config: &mut Config,
        config_path: &Path,
    ) -> Result<ActionResult> {
        match action {
            DotfileAction::ScanDotfiles => {
                self.scan_dotfiles(config)?;
                Ok(ActionResult::None)
            }
            DotfileAction::RefreshFileBrowser => {
                self.refresh_file_browser(config)?;
                Ok(ActionResult::None)
            }
            DotfileAction::ToggleFileSync { file_index, is_synced } => {
                self.toggle_file_sync(config, file_index, is_synced)
            }
            DotfileAction::AddCustomFileToSync { full_path, relative_path } => {
                self.add_custom_file_to_sync(config, config_path, full_path, relative_path)
            }
            DotfileAction::SetBackupEnabled { enabled } => {
                config.backup_enabled = enabled;
                config.save(config_path)?;
                self.state.backup_enabled = enabled;
                Ok(ActionResult::None)
            }
            DotfileAction::MoveToCommon { file_index, is_common, profiles_to_cleanup } => {
                self.move_to_common(config, file_index, is_common, profiles_to_cleanup)
            }
        }
    }

    /// Scan for dotfiles and populate the selection state
    fn scan_dotfiles(&mut self, config: &Config) -> Result<()> {
        let found = SyncService::scan_dotfiles(config)?;

        let selected_indices: std::collections::HashSet<usize> = found
            .iter()
            .enumerate()
            .filter(|(_, d)| d.synced)
            .map(|(i, _)| i)
            .collect();

        self.state.dotfiles = found;
        self.state.preview_index = None;
        self.state.preview_scroll = 0;
        self.state.selected_for_sync = selected_indices;

        if !self.state.dotfiles.is_empty() {
            self.state.dotfile_list_state.select(Some(0));
        } else {
            self.state.dotfile_list_state.select(None);
        }

        Ok(())
    }

    /// Refresh file browser entries for current directory
    fn refresh_file_browser(&mut self, config: &Config) -> Result<()> {
        let path = &self.state.file_browser_path;
        let mut entries = Vec::new();

        // Add parent directory if not at root
        if path != std::path::Path::new("/") && path.parent().is_some() {
            entries.push(PathBuf::from(".."));
        }

        // Add special marker for "add this folder"
        let repo_path = &config.repo_path;
        let (is_safe, _) = crate::utils::is_safe_to_add(path, repo_path);
        if is_safe && path.is_dir() {
            entries.push(PathBuf::from("."));
        }

        // Read directory entries
        if let Ok(entries_iter) = std::fs::read_dir(path) {
            for entry in entries_iter.flatten() {
                entries.push(entry.path());
            }
        }

        // Sort: special entries first, then directories, then files
        entries.sort_by(|a, b| {
            let a_is_special = a == std::path::Path::new("..") || a == std::path::Path::new(".");
            let b_is_special = b == std::path::Path::new("..") || b == std::path::Path::new(".");

            if a_is_special && b_is_special {
                if a == std::path::Path::new("..") {
                    return std::cmp::Ordering::Less;
                } else {
                    return std::cmp::Ordering::Greater;
                }
            }
            if a_is_special { return std::cmp::Ordering::Less; }
            if b_is_special { return std::cmp::Ordering::Greater; }

            let a_is_dir = a.is_dir();
            let b_is_dir = b.is_dir();

            match (a_is_dir, b_is_dir) {
                (true, false) => std::cmp::Ordering::Less,
                (false, true) => std::cmp::Ordering::Greater,
                _ => {
                    let a_name = a.file_name().and_then(|n| n.to_str()).unwrap_or("");
                    let b_name = b.file_name().and_then(|n| n.to_str()).unwrap_or("");
                    a_name.cmp(b_name)
                }
            }
        });

        self.state.file_browser_entries = entries;

        // Update selection to be within bounds
        if let Some(current) = self.state.file_browser_list_state.selected() {
            if current >= self.state.file_browser_entries.len() {
                if self.state.file_browser_entries.is_empty() {
                    self.state.file_browser_list_state.select(None);
                } else {
                    self.state.file_browser_list_state.select(Some(self.state.file_browser_entries.len() - 1));
                }
            }
        } else if !self.state.file_browser_entries.is_empty() {
            self.state.file_browser_list_state.select(Some(0));
        }

        Ok(())
    }

    /// Toggle file sync status (add or remove from sync)
    fn toggle_file_sync(
        &mut self,
        config: &Config,
        file_index: usize,
        is_synced: bool,
    ) -> Result<ActionResult> {
        if file_index >= self.state.dotfiles.len() {
            warn!("File index {} out of bounds", file_index);
            return Ok(ActionResult::None);
        }

        let dotfile = &self.state.dotfiles[file_index];
        let filename = dotfile.relative_path.to_string_lossy().to_string();
        let is_common = dotfile.is_common;

        if is_synced {
            // Removing from sync
            if is_common {
                return Ok(ActionResult::ShowDialog {
                    title: "Cannot Unsync Common File".to_string(),
                    content: format!(
                        "\"{}\" is a common file shared across all profiles.\n\n\
                        To remove it from sync, first move it to your profile \
                        using the 'Move to Profile' action, then unsync it.",
                        filename
                    ),
                    variant: crate::widgets::DialogVariant::Warning,
                });
            }

            self.remove_file_from_sync(config, file_index)?;
            Ok(ActionResult::ShowToast {
                message: format!("Removed: {}", filename),
                variant: crate::widgets::ToastVariant::Success,
            })
        } else {
            // Adding to sync
            self.add_file_to_sync(config, file_index)?;

            if let Some(error_msg) = self.state.status_message.take() {
                Ok(ActionResult::ShowDialog {
                    title: "Sync Failed".to_string(),
                    content: error_msg,
                    variant: crate::widgets::DialogVariant::Error,
                })
            } else {
                Ok(ActionResult::ShowToast {
                    message: format!("Added: {}", filename),
                    variant: crate::widgets::ToastVariant::Success,
                })
            }
        }
    }

    /// Add a file to sync
    fn add_file_to_sync(&mut self, config: &Config, file_index: usize) -> Result<()> {
        if file_index >= self.state.dotfiles.len() {
            return Ok(());
        }

        let dotfile = &self.state.dotfiles[file_index];
        let relative_str = dotfile.relative_path.to_string_lossy().to_string();
        let full_path = dotfile.original_path.clone();

        match SyncService::add_file_to_sync(config, &full_path, &relative_str, self.state.backup_enabled)? {
            crate::services::AddFileResult::Success => {
                self.state.selected_for_sync.insert(file_index);
                self.state.dotfiles[file_index].synced = true;
                info!("Successfully added file to sync: {}", relative_str);
            }
            crate::services::AddFileResult::AlreadySynced => {
                self.state.selected_for_sync.insert(file_index);
                debug!("File already synced: {}", relative_str);
            }
            crate::services::AddFileResult::ValidationFailed(error_msg) => {
                self.state.status_message = Some(format!("Error: {}", error_msg));
                warn!("Validation failed for {}: {}", relative_str, error_msg);
            }
        }

        Ok(())
    }

    /// Remove a file from sync
    fn remove_file_from_sync(&mut self, config: &Config, file_index: usize) -> Result<()> {
        if file_index >= self.state.dotfiles.len() {
            return Ok(());
        }

        let relative_str = self.state.dotfiles[file_index]
            .relative_path
            .to_string_lossy()
            .to_string();

        match SyncService::remove_file_from_sync(config, &relative_str)? {
            crate::services::RemoveFileResult::Success => {
                self.state.selected_for_sync.remove(&file_index);
                self.state.dotfiles[file_index].synced = false;
                info!("Successfully removed file from sync: {}", relative_str);
            }
            crate::services::RemoveFileResult::NotSynced => {
                debug!("File not synced, skipping removal: {}", relative_str);
                self.state.selected_for_sync.remove(&file_index);
            }
        }

        Ok(())
    }

    /// Add a custom file to sync
    fn add_custom_file_to_sync(
        &mut self,
        config: &mut Config,
        config_path: &Path,
        full_path: PathBuf,
        relative_path: String,
    ) -> Result<ActionResult> {
        match SyncService::add_file_to_sync(config, &full_path, &relative_path, self.state.backup_enabled)? {
            crate::services::AddFileResult::Success => {
                // Add to custom_files if not already there
                if SyncService::is_custom_file(&relative_path) {
                    if !config.custom_files.contains(&relative_path) {
                        config.custom_files.push(relative_path.clone());
                        config.save(config_path)?;
                    }
                }
                info!("Successfully added custom file to sync: {}", relative_path);

                // Re-scan to refresh the list
                self.scan_dotfiles(config)?;

                // Find and select the file
                if let Some(index) = self.state.dotfiles.iter().position(|d| {
                    d.relative_path.to_string_lossy() == relative_path
                }) {
                    self.state.dotfile_list_state.select(Some(index));
                    self.state.selected_for_sync.insert(index);
                }

                Ok(ActionResult::ShowToast {
                    message: format!("Added: {}", relative_path),
                    variant: crate::widgets::ToastVariant::Success,
                })
            }
            crate::services::AddFileResult::AlreadySynced => {
                debug!("Custom file already synced: {}", relative_path);
                Ok(ActionResult::None)
            }
            crate::services::AddFileResult::ValidationFailed(error_msg) => {
                warn!("Validation failed for custom file {}: {}", relative_path, error_msg);
                Ok(ActionResult::ShowDialog {
                    title: "Sync Failed".to_string(),
                    content: error_msg,
                    variant: crate::widgets::DialogVariant::Error,
                })
            }
        }
    }

    /// Move a file to/from common
    fn move_to_common(
        &mut self,
        config: &Config,
        file_index: usize,
        is_common: bool,
        profiles_to_cleanup: Vec<String>,
    ) -> Result<ActionResult> {
        if file_index >= self.state.dotfiles.len() {
            return Ok(ActionResult::None);
        }

        let relative_path = self.state.dotfiles[file_index]
            .relative_path
            .to_string_lossy()
            .to_string();

        if is_common {
            // Move FROM common TO profile
            match SyncService::move_from_common(config, &relative_path) {
                Ok(_) => {
                    info!("Moved {} from common to profile", relative_path);
                    self.scan_dotfiles(config)?;

                    // Find and update the file in the list
                    if let Some(idx) = self.state.dotfiles.iter().position(|d| {
                        d.relative_path.to_string_lossy() == relative_path
                    }) {
                        self.state.dotfiles[idx].is_common = false;
                        self.state.dotfiles[idx].synced = true;
                        self.state.selected_for_sync.insert(idx);
                        self.state.dotfile_list_state.select(Some(idx));
                    }

                    Ok(ActionResult::ShowToast {
                        message: format!("Moved to profile: {}", relative_path),
                        variant: crate::widgets::ToastVariant::Success,
                    })
                }
                Err(e) => {
                    error!("Failed to move from common: {}", e);
                    Ok(ActionResult::ShowDialog {
                        title: "Move Failed".to_string(),
                        content: format!("Failed to move file from common:\n\n{}", e),
                        variant: crate::widgets::DialogVariant::Error,
                    })
                }
            }
        } else {
            // Move FROM profile TO common
            let result = if !profiles_to_cleanup.is_empty() {
                SyncService::move_to_common_with_cleanup(config, &relative_path, &profiles_to_cleanup)
            } else {
                SyncService::move_to_common(config, &relative_path)
            };

            match result {
                Ok(_) => {
                    info!("Moved {} to common", relative_path);
                    self.scan_dotfiles(config)?;

                    // Find and update the file in the list
                    if let Some(idx) = self.state.dotfiles.iter().position(|d| {
                        d.relative_path.to_string_lossy() == relative_path
                    }) {
                        self.state.dotfiles[idx].is_common = true;
                        self.state.dotfiles[idx].synced = true;
                        self.state.selected_for_sync.insert(idx);
                        self.state.dotfile_list_state.select(Some(idx));
                    }

                    Ok(ActionResult::ShowToast {
                        message: format!("Moved to common: {}", relative_path),
                        variant: crate::widgets::ToastVariant::Success,
                    })
                }
                Err(e) => {
                    error!("Failed to move to common: {}", e);
                    Ok(ActionResult::ShowDialog {
                        title: "Move Failed".to_string(),
                        content: format!("Failed to move file to common:\n\n{}", e),
                        variant: crate::widgets::DialogVariant::Error,
                    })
                }
            }
        }
    }
