    /// Process a profile-specific action
    pub fn process_action(
        &mut self,
        action: ProfileAction,
        config: &mut Config,
        config_path: &Path,
    ) -> Result<ActionResult> {
        match action {
            ProfileAction::CreateProfile { name, description, copy_from } => {
                self.create_profile(config, &name, description, copy_from)
            }
            ProfileAction::SwitchProfile { name } => {
                self.switch_profile(config, config_path, &name)
            }
            ProfileAction::RenameProfile { old_name, new_name } => {
                self.rename_profile(config, config_path, &old_name, &new_name)
            }
            ProfileAction::DeleteProfile { name } => {
                self.delete_profile(config, &name)
            }
        }
    }

    fn create_profile(
        &mut self,
        config: &Config,
        name: &str,
        description: Option<String>,
        copy_from: Option<usize>,
    ) -> Result<ActionResult> {
        match ProfileService::create_profile(&config.repo_path, name, description, copy_from) {
            Ok(_) => {
                if let Err(e) = self.refresh_profiles(&config.repo_path) {
                    error!("Failed to refresh profiles after creation: {}", e);
                }
                Ok(ActionResult::None)
            }
            Err(e) => {
                error!("Failed to create profile: {}", e);
                Ok(ActionResult::ShowDialog {
                    title: "Profile Creation Failed".to_string(),
                    content: format!("Failed to create profile '{}':\n\n{}", name, e),
                    variant: crate::widgets::DialogVariant::Error,
                })
            }
        }
    }

    fn switch_profile(
        &mut self,
        config: &mut Config,
        config_path: &Path,
        target_name: &str,
    ) -> Result<ActionResult> {
        if config.active_profile == target_name {
            return Ok(ActionResult::None);
        }

        let old_profile = config.active_profile.clone();

        match ProfileService::switch_profile(
            &config.repo_path,
            &old_profile,
            target_name,
            config.backup_enabled,
        ) {
            Ok(_result) => {
                config.active_profile = target_name.to_string();
                config.save(config_path)?;
                info!("Switched to profile: {}", target_name);
                Ok(ActionResult::None)
            }
            Err(e) => {
                error!("Failed to switch profile: {}", e);
                Ok(ActionResult::ShowDialog {
                    title: "Switch Profile Failed".to_string(),
                    content: format!("Failed to switch to profile '{}':\n\n{}", target_name, e),
                    variant: crate::widgets::DialogVariant::Error,
                })
            }
        }
    }

    fn rename_profile(
        &mut self,
        config: &mut Config,
        config_path: &Path,
        old_name: &str,
        new_name: &str,
    ) -> Result<ActionResult> {
        let was_active = config.active_profile == old_name;
        let is_activated = config.profile_activated && was_active;

        match ProfileService::rename_profile(
            &config.repo_path,
            old_name,
            new_name,
            is_activated,
            config.backup_enabled,
        ) {
            Ok(sanitized_name) => {
                if was_active {
                    config.active_profile = sanitized_name;
                    config.save(config_path)?;
                }
                if let Err(e) = self.refresh_profiles(&config.repo_path) {
                    error!("Failed to refresh profiles after rename: {}", e);
                }
                Ok(ActionResult::None)
            }
            Err(e) => {
                error!("Failed to rename profile: {}", e);
                Ok(ActionResult::ShowDialog {
                    title: "Rename Failed".to_string(),
                    content: format!("Failed to rename profile '{}':\n\n{}", old_name, e),
                    variant: crate::widgets::DialogVariant::Error,
                })
            }
        }
    }

    fn delete_profile(&mut self, config: &Config, name: &str) -> Result<ActionResult> {
        match ProfileService::delete_profile(&config.repo_path, name, &config.active_profile) {
            Ok(_) => {
                if let Err(e) = self.refresh_profiles(&config.repo_path) {
                    error!("Failed to refresh profiles after deletion: {}", e);
                }
                Ok(ActionResult::None)
            }
            Err(e) => {
                error!("Failed to delete profile: {}", e);
                Ok(ActionResult::ShowDialog {
                    title: "Delete Failed".to_string(),
                    content: format!("Failed to delete profile '{}':\n\n{}", name, e),
                    variant: crate::widgets::DialogVariant::Error,
                })
            }
        }
    }
