                        })
                    }
                }
            }
            ProfileSelectionAction::ActivateProfile { name } => {
                self.activate_profile(config, config_path, &name)
            }
        }
    }

    fn activate_profile(
        &mut self,
        config: &mut Config,
        config_path: &Path,
        profile_name: &str,
    ) -> Result<ActionResult> {
        info!("Activating profile '{}' after setup", profile_name);

        config.active_profile = profile_name.to_string();
        config.save(config_path)?;

        match ProfileService::activate_profile(
            &config.repo_path,
            profile_name,
            config.backup_enabled,
