                config.save(config_path)?;
                self.reset();
                Ok(ActionResult::Navigate(crate::ui::Screen::MainMenu))
            }
            Err(e) => {
                error!("Failed to activate profile: {}", e);
                Ok(ActionResult::ShowDialog {
                    title: "Activation Failed".to_string(),
                    content: e.to_string(),
                    variant: crate::widgets::DialogVariant::Error,
                })
            }
        }
    }
