//! Shared utilities for CLI commands.

use crate::config::Config;
use crate::utils::ProfileManifest;
use anyhow::{Context, Result};
use std::io::{self, Write};
use std::path::PathBuf;

/// Shared context for CLI commands.
pub struct CliContext {
    pub config: Config,
    pub manifest: ProfileManifest,
    pub config_path: PathBuf,
}

impl CliContext {
    /// Load config and manifest, exit with error if not configured.
    pub fn load() -> Result<Self> {
        let config_path = crate::utils::get_config_path();
        let config = Config::load_or_create(&config_path)
            .context("Failed to load configuration")?;

        if !config.is_repo_configured() {
            print_error("Repository not configured. Run 'dotstate' to set up repository.");
            std::process::exit(1);
        }

        let manifest = ProfileManifest::load_or_backfill(&config.repo_path)
            .context("Failed to load profile manifest")?;

        Ok(Self {
            config,
            manifest,
            config_path,
        })
    }

    /// Resolve profile name (use provided or fall back to active).
    pub fn resolve_profile<'a>(&'a self, profile: Option<&'a str>) -> &'a str {
        profile.unwrap_or(&self.config.active_profile)
    }

    /// Check if profile is the active profile.
    pub fn is_active_profile(&self, profile: &str) -> bool {
        self.config.active_profile == profile
    }

    /// Check if profile exists in manifest.
    pub fn profile_exists(&self, profile: &str) -> bool {
        self.manifest.profiles.iter().any(|p| p.name == profile)
    }
}

// Output helpers
pub fn print_success(msg: &str) {
    println!("✓ {}", msg);
}

pub fn print_error(msg: &str) {
    eprintln!("❌ {}", msg);
}

pub fn print_warning(msg: &str) {
    println!("⚠️  {}", msg);
}

pub fn print_info(msg: &str) {
    println!("ℹ️  {}", msg);
}

/// Prompt for text input with optional default.
pub fn prompt_string(label: &str, default: Option<&str>) -> Result<String> {
    if let Some(def) = default {
        print!("{} [{}]: ", label, def);
    } else {
        print!("{}: ", label);
    }
    io::stdout().flush()?;

    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let trimmed = input.trim();

    if trimmed.is_empty() {
        Ok(default.unwrap_or("").to_string())
    } else {
        Ok(trimmed.to_string())
    }
}

/// Prompt for optional text input (empty string returns None).
pub fn prompt_string_optional(label: &str) -> Result<Option<String>> {
    print!("{} (optional, press Enter to skip): ", label);
    io::stdout().flush()?;

    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let trimmed = input.trim();

    if trimmed.is_empty() {
        Ok(None)
    } else {
        Ok(Some(trimmed.to_string()))
    }
}

/// Prompt for selection from numbered list.
/// Returns the index of the selected option.
pub fn prompt_select(label: &str, options: &[(&str, Option<&str>)]) -> Result<usize> {
    println!("{}:", label);
    for (i, (name, suffix)) in options.iter().enumerate() {
        if let Some(s) = suffix {
            println!("  {}. {} {}", i + 1, name, s);
        } else {
            println!("  {}. {}", i + 1, name);
        }
    }
    print!("Select [1-{}]: ", options.len());
    io::stdout().flush()?;

    let mut input = String::new();
    io::stdin().read_line(&mut input)?;

    let choice: usize = input.trim().parse()
        .context("Invalid selection")?;

    if choice < 1 || choice > options.len() {
        anyhow::bail!("Selection out of range");
    }

    Ok(choice - 1)
}

/// Prompt for y/N confirmation.
pub fn prompt_confirm(message: &str) -> Result<bool> {
    print!("{} [y/N]: ", message);
    io::stdout().flush()?;

    let mut input = String::new();
    io::stdin().read_line(&mut input)?;

    let trimmed = input.trim().to_lowercase();
    Ok(trimmed == "y" || trimmed == "yes")
}
```

